#!/usr/bin/env bash
set -euo pipefail

# Drift check for the generated MCP API reference. The servers under tools/mcp/
# are the single source of truth; docs/mcp/api-reference.{json,html} are
# generated by scripts/generate-mcp-api-reference.mjs and must be regenerated
# (make mcp-api-reference) whenever a tool is added, removed, or its
# description/input schema changes.
#
# --baseRef=origin/main (LS-10149): on a TOTAL budget violation, also measures
# origin/main via git plumbing (no worktree) so the failure message says
# whether the base ref or this branch owns the overage, instead of always
# pointing at the branch. This checkout runs with fetch-depth: 0, so
# origin/main is always resolvable here.
echo "Checking MCP API reference sync..."
node scripts/generate-mcp-api-reference.mjs --check --baseRef=origin/main
echo "MCP API reference sync check passed"
